class FakeResource:
    def __init__(self, fail_commit=False, fail_rollback=False):
        self.events = []
        self.fail_commit = fail_commit
        self.fail_rollback = fail_rollback
    def begin(self):
        self.events.append("begin")
    def commit(self):
        self.events.append("commit")
        if self.fail_commit:
            raise IOError("commit failed")
    def rollback(self):
        self.events.append("rollback")
        if self.fail_rollback:
            raise RuntimeError("rollback failed")

for make in (Transaction, transaction):
    # success
    r = FakeResource()
    with make(r) as got:
        assert got is r
        r.events.append("work")
    assert r.events == ["begin", "work", "commit"]

    # body raises: rollback, exception propagates unchanged
    r = FakeResource()
    seen = None
    try:
        with make(r):
            raise ValueError("boom")
    except ValueError as e:
        seen = e
    assert seen is not None and seen.args == ("boom",)
    assert r.events == ["begin", "rollback"]

    # KeyboardInterrupt also rolls back
    r = FakeResource()
    try:
        with make(r):
            raise KeyboardInterrupt()
    except KeyboardInterrupt:
        pass
    else:
        raise AssertionError("must propagate")
    assert r.events == ["begin", "rollback"]

    # commit fails: rollback, commit error propagates
    r = FakeResource(fail_commit=True)
    try:
        with make(r):
            pass
    except IOError as e:
        assert str(e) == "commit failed"
    else:
        raise AssertionError("must propagate")
    assert r.events == ["begin", "commit", "rollback"]

    # rollback failure is chained to the original error
    r = FakeResource(fail_rollback=True)
    try:
        with make(r):
            raise ValueError("orig")
    except RuntimeError as e:
        assert isinstance(e.__context__, ValueError)
    else:
        raise AssertionError("rollback error should propagate")

